"use strict";
const APP={name:"REMESAS",version:"4.2.1",lang:localStorage.getItem("remesas_lang_v4")||"es",token:localStorage.getItem("remesas_access_token_v4")||"",session:null,config:null,moneyKey:"remesas_money_v4",incomeKey:"remesas_income_v4",expensesKey:"remesas_expenses_v4",familyKey:"remesas_family_v4",savingsKey:"remesas_savings_v4",purchasesKey:"remesas_purchases_v4",prefsKey:"remesas_prefs_v4",tapCount:0,tapTimer:null,expiresAt:0,countdown:null};
const $=s=>document.querySelector(s),app=$("#app");
const t=(es,en)=>APP.lang==="es"?es:en;
const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const arr=v=>Array.isArray(v)?v:v==null?[]:[v];
const text=v=>typeof v==="string"||typeof v==="number"?String(v):v&&typeof v==="object"?String(v.text||v.title||v.name||v.description||v.label||v.value||""):String(v??"");
const money=(v,c="USD")=>{let n=Number(v||0);return n.toLocaleString(APP.lang==="es"?"es-US":"en-US",{style:"currency",currency:c})};
const now=()=>new Date(),dateTime=()=>now().toLocaleString(APP.lang==="es"?"es-US":"en-US",{dateStyle:"short",timeStyle:"short"}),day=()=>now().toLocaleDateString(APP.lang==="es"?"es-US":"en-US",{weekday:"long"});
const save=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const load=(k,d)=>{try{let v=localStorage.getItem(k);return v===null?d:JSON.parse(v)}catch(e){return d}};
const headers=(json=true)=>{let h={"X-Remesas-Language":APP.lang};if(APP.token)h["X-Remesas-Access-Token"]=APP.token;if(json)h["Content-Type"]="application/json";return h};
async function api(url,opt={}){let c=new AbortController(),tm=setTimeout(()=>c.abort(),20000);opt={...opt,signal:c.signal,headers:{...headers(opt.body!==undefined),...(opt.headers||{})}};try{let r=await fetch(url,opt),tx=await r.text(),d={};try{d=tx?JSON.parse(tx):{}}catch(e){d={detail:tx}}if(!r.ok){if(r.status===401||r.status===403){setToken("");APP.session=null;gate()}throw Error(d.detail||d.message||t("No se pudo completar la acción.","The action could not be completed."))}return d}catch(e){if(e.name==="AbortError")throw Error(t("La respuesta tardó demasiado.","The response took too long."));throw e}finally{clearTimeout(tm)}}
function toast(msg,type=""){let x=document.createElement("div");x.className="toast "+type;x.textContent=msg;document.body.appendChild(x);setTimeout(()=>x.remove(),3500)}
function setToken(x){APP.token=x||"";if(APP.token)localStorage.setItem("remesas_access_token_v4",APP.token);else localStorage.removeItem("remesas_access_token_v4")}
function mergeSession(d){if(d&&d.session)APP.session=d.session;else if(d&&d.session_id&&APP.session)APP.session={...APP.session,...d};return APP.session}
function safeUrl(u){u=String(u||"");return /^https?:\/\//i.test(u)?u:""}
function countryList(){let c=APP.config?.countries;if(Array.isArray(c)&&c.length)return c;return[{code:"MX",name:"México"},{code:"GT",name:"Guatemala"},{code:"SV",name:"El Salvador"},{code:"HN",name:"Honduras"},{code:"NI",name:"Nicaragua"},{code:"CR",name:"Costa Rica"},{code:"PA",name:"Panamá"},{code:"CO",name:"Colombia"},{code:"VE",name:"Venezuela"},{code:"EC",name:"Ecuador"},{code:"PE",name:"Perú"},{code:"BO",name:"Bolivia"},{code:"PY",name:"Paraguay"},{code:"CL",name:"Chile"},{code:"AR",name:"Argentina"},{code:"BR",name:"Brasil"},{code:"DO",name:"República Dominicana"},{code:"CU",name:"Cuba"},{code:"UY",name:"Uruguay"},{code:"JM",name:"Jamaica"}]}
function providers(){let p=APP.config?.providers;if(Array.isArray(p)&&p.length)return p;return[{id:"western_union",name:"Western Union"},{id:"moneygram",name:"MoneyGram"},{id:"remitly",name:"Remitly"},{id:"xoom",name:"Xoom"}]}
const delivery=[["bank_account","Cuenta bancaria"],["cash_pickup","Recogida en efectivo"],["debit_card","Tarjeta de débito"],["mobile_wallet","Billetera móvil"],["home_delivery","Entrega a domicilio"],["other","Otra opción"]];
const payment=[["bank_account","Cuenta bancaria"],["debit_card","Tarjeta de débito"],["credit_card","Tarjeta de crédito"],["cash","Efectivo"],["digital_wallet","Billetera digital"]];
const priorities=[["fastest","Rapidez"],["save","Ahorrar"],["recipient_gets_more","Que reciba más"],["urgent","Urgente"],["balanced","Equilibrado"],["compare_all","Ver todas"],["other","Otra prioridad"]];
function options(list,val=""){return list.map(x=>`<option value="${esc(x[0])}"${val===x[0]?" selected":""}>${esc(t(x[1],x[1]))}</option>`).join("")}
function countryOptions(val=""){return `<option value="">${t("Selecciona un país","Select a country")}</option>`+countryList().map(c=>{let code=c.code||c.id||c.iso2||"",name=c.name||c.label||code;return`<option value="${esc(code)}"${val===code?" selected":""}>${esc(name)}</option>`}).join("")}
function shell(body,title="REMESAS"){app.innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand"><strong>${esc(title)}</strong><small>May Roga LLC</small></div><div class="top-actions"><button class="btn small lang-btn" id="langBtn">${APP.lang==="es"?"EN":"ES"}</button><button class="btn secondary small" id="homeBtn">⌂</button></div></header>${body}<footer class="footer"><strong>REMESAS ${APP.version}</strong><span>May Roga LLC</span><div class="footer-links"><button class="btn small secondary" data-go="help">${t("Ayuda","Help")}</button><button class="btn small secondary" data-go="privacy">${t("Privacidad","Privacy")}</button></div></footer></div>`;bindShell()}
function bindShell(){$("#langBtn")?.addEventListener("click",async()=>{APP.lang=APP.lang==="es"?"en":"es";localStorage.setItem("remesas_lang_v4",APP.lang);await loadConfig();if(APP.token&&await verify())await startService();else gate()});$("#homeBtn")?.addEventListener("click",home);document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>route(b.dataset.go))}
function gate(){clearInterval(APP.countdown);app.innerHTML=`<main class="app-shell"><section class="hero" id="gateArea"><div class="hero-badge">REMESAS · May Roga LLC</div><h1>${t("TU DINERO, MÁS CLARO","YOUR MONEY, CLEARER")}</h1><p>${t("Organiza tu dinero, prepara una remesa, aprende el proceso y revisa opciones oficiales.","Organize your money, prepare a remittance, learn the process and review official options.")}</p><div class="hero-actions"><button class="btn" id="payBtn">${t("Entrar por $10.99 · 20 minutos","Enter for $10.99 · 20 minutes")}</button><button class="btn secondary" id="infoBtn">${t("¿Qué incluye?","What is included?")}</button></div><div class="notice">${t("Servicio independiente. No somos banco, financiera, transmisor de dinero ni procesador de pagos. No hacemos la transferencia por ti.","Independent service. We are not a bank, financial institution, money transmitter or payment processor. We do not execute the transfer for you.")}</div></section><section class="section"><div class="card"><h2>${t("¿Qué puedes hacer?","What can you do?")}</h2><div class="grid two"><div class="card"><strong>1. ${t("ORGANIZAR","ORGANIZE")}</strong><p>TENGO → GANO → GASTO → AHORRO → QUIERO → PUEDO → HAGO</p></div><div class="card"><strong>2. ${t("PREPARAR","PREPARE")}</strong><p>${t("Monto, país, necesidad y datos necesarios antes de ir al proveedor oficial.","Amount, country, need and required information before going to the official provider.")}</p></div><div class="card"><strong>3. ${t("APRENDER","LEARN")}</strong><p>${t("Explicaciones originales y sencillas del proceso.","Original, simple explanations of the process.")}</p></div><div class="card"><strong>4. ${t("COMPARAR","COMPARE")}</strong><p>${t("Datos comerciales solamente cuando están verificados.","Commercial data only when verified.")}</p></div></div></div></section></main>`;$("#payBtn").onclick=pay;$("#infoBtn").onclick=serviceInfo;tripleTap()}
function tripleTap(){let a=$("#gateArea");if(!a)return;a.addEventListener("click",e=>{if(e.target.closest("button,a,input,textarea,select"))return;APP.tapCount++;clearTimeout(APP.tapTimer);APP.tapTimer=setTimeout(()=>APP.tapCount=0,900);if(APP.tapCount>=3){APP.tapCount=0;adminModal()}})}
async function serviceInfo(){try{let d=await api("/api/service/info");let f=arr(d.features||d.includes||[]);modal(t("Servicio","Service"),`<p>${esc(d.description||t("Acceso único de $10.99 por 20 minutos.","One-time access of $10.99 for 20 minutes."))}</p><ul><li>${t("Precio:","Price:")} ${esc(d.price??"10.99")} ${esc(d.currency||"USD")}</li><li>${t("Duración:","Duration:")} ${esc(d.minutes??20)} ${t("minutos","minutes")}</li>${f.map(x=>`<li>${esc(text(x))}</li>`).join("")}</ul>`)}catch(e){modal(t("Servicio","Service"),`<p>${t("Acceso único: $10.99 por 20 minutos.","One-time access: $10.99 for 20 minutes.")}</p>`)}}
function adminModal(){modal(t("Acceso de administración","Administration access"),`<form id="adminForm" class="form-card"><div class="field"><label>${t("Usuario","Username")}</label><input id="adminUser" autocomplete="username" required></div><div class="field"><label>${t("Contraseña","Password")}</label><input id="adminPass" type="password" autocomplete="current-password" required></div><button class="btn">${t("Entrar","Enter")}</button></form>`);$("#adminForm").onsubmit=async e=>{e.preventDefault();try{let d=await api("/api/access/admin",{method:"POST",body:JSON.stringify({username:$("#adminUser").value,password:$("#adminPass").value})});if(!d.token)throw Error(t("Acceso no autorizado.","Access not authorized."));setToken(d.token);APP.expiresAt=d.expires_at||Date.now()+Number(d.seconds||1200)*1000;closeModal();await startService()}catch(e){toast(e.message,"error")}}}
async function pay(){try{let d=await api("/api/create-checkout-session",{method:"POST",body:"{}"});let u=safeUrl(d.checkout_url);if(!u)throw Error(t("No se recibió la página de pago.","Payment page was not received."));location.href=u}catch(e){toast(e.message,"error")}}
function modal(title,body){$("#modal")?.remove();let m=document.createElement("div");m.className="modal-backdrop";m.id="modal";m.innerHTML=`<div class="modal"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" id="closeModal">×</button></div><div>${body}</div></div>`;document.body.appendChild(m);$("#closeModal").onclick=closeModal;m.onclick=e=>{if(e.target===m)closeModal()}}
function closeModal(){$("#modal")?.remove()}
async function checkPayment(){let q=new URLSearchParams(location.search);if(q.get("payment")==="success"&&q.get("session_id")){try{let d=await api("/api/payment/check?session_id="+encodeURIComponent(q.get("session_id")),{});if(d.token)setToken(d.token);history.replaceState({},document.title,"/");if(APP.token){await startService();return true}}catch(e){history.replaceState({},document.title,"/");toast(e.message,"error")}}if(q.get("payment")==="cancelled"){history.replaceState({},document.title,"/");toast(t("Pago cancelado.","Payment cancelled."))}return false}
async function verify(){if(!APP.token)return false;try{let d=await api("/api/access/status");if(d.active||d.authorized){APP.expiresAt=d.expires_at||Date.now()+Number(d.seconds_remaining||1200)*1000;return true}}catch(e){}setToken("");return false}
async function startService(){try{let d=await api("/api/service/start",{method:"POST",body:"{}"});APP.session=d.session||APP.session;APP.expiresAt=d.expires_at||Date.now()+Number(d.seconds_remaining||1200)*1000;home()}catch(e){setToken("");APP.session=null;gate();toast(e.message,"error")}}
async function boot(){await loadConfig();if(await checkPayment())return;if(await verify()){await startService();return}gate()}
function home(){if(!APP.token){gate();return}let m=load(APP.moneyKey,{income:0,balance:0}),ex=load(APP.expensesKey,[]),fam=load(APP.familyKey,[]),sav=load(APP.savingsKey,[]),pur=load(APP.purchasesKey,[]),inc=load(APP.incomeKey,[]);shell(`<section class="hero"><h1>${t("TU DINERO, MÁS CLARO","YOUR MONEY, CLEARER")}</h1><p>${t("Empieza donde lo necesites. Tus registros de dinero permanecen en este dispositivo.","Start where you need. Your money records stay on this device.")}</p><div class="hero-actions"><button class="btn" data-action="send">${t("PREPARAR REMESA","PREPARE REMITTANCE")}</button><button class="btn secondary" data-action="learn">${t("APRENDER","LEARN")}</button><button class="btn secondary" data-action="compare">${t("COMPARAR","COMPARE")}</button></div></section><section class="section"><h2 class="section-title">${t("Tu ciclo","Your cycle")}</h2><div class="grid three"><button class="action-card" data-action="money"><span class="action-icon">💵</span><strong>TENGO</strong><small>${t("Lo que tienes ahora","What you have now")}</small></button><button class="action-card" data-action="income"><span class="action-icon">➕</span><strong>GANO</strong><small>${t("Lo que entra","What comes in")}</small></button><button class="action-card" data-action="expenses"><span class="action-icon">➖</span><strong>GASTO</strong><small>${t("Lo que sale","What goes out")}</small></button><button class="action-card" data-action="savings"><span class="action-icon">🏦</span><strong>AHORRO</strong><small>${t("Lo que separas","What you set aside")}</small></button><button class="action-card" data-action="purchase"><span class="action-icon">🛒</span><strong>QUIERO</strong><small>${t("Lo que planeas comprar","What you plan to buy")}</small></button><button class="action-card" data-action="week"><span class="action-icon">📅</span><strong>PUEDO</strong><small>${t("Lo que puedes hacer","What you can do")}</small></button><button class="action-card" data-action="do"><span class="action-icon">✅</span><strong>HAGO</strong><small>${t("La acción que sigue","The next action")}</small></button><button class="action-card" data-action="family"><span class="action-icon">👨‍👩‍👧</span><strong>${t("FAMILIA","FAMILY")}</strong><small>${t("Personas y necesidades","People and needs")}</small></button></div></section><section class="section"><div class="balance-grid"><div class="balance"><small>${t("Disponible","Available")}</small><strong>${money(m.balance)}</strong></div><div class="balance"><small>${t("Ingresos","Income")}</small><strong>${money(m.income)}</strong></div><div class="balance"><small>${t("Gastos registrados","Recorded expenses")}</small><strong>${ex.length}</strong></div><div class="balance"><small>${t("Ahorros","Savings")}</small><strong>${sav.length}</strong></div></div></section><section class="section"><div class="card"><h2>${t("También puedes","You can also")}</h2><div class="hero-actions"><button class="btn secondary" data-action="guide">${t("GUÍA RÁPIDA","QUICK GUIDE")}</button><button class="btn secondary" data-action="pdf">${t("PDF DE MI DINERO","MY MONEY PDF")}</button><button class="btn secondary" data-action="learnpdf">${t("PDF APRENDER","LEARN PDF")}</button><button class="btn secondary" data-action="assistant">${t("ASISTENTE","ASSISTANT")}</button><button class="btn secondary" data-action="help">${t("AYUDA","HELP")}</button></div></div></section><section class="section"><div class="notice">${t("Acceso temporal:","Temporary access:")} <strong id="countdown"></strong></div></section>`);document.querySelectorAll("[data-action]").forEach(b=>b.onclick=()=>route(b.dataset.action));startCountdown();void inc;void pur;void fam}
function startCountdown(){clearInterval(APP.countdown);let f=()=>{let sec=Math.max(0,Math.floor((new Date(APP.expiresAt).getTime()-Date.now())/1000)),m=Math.floor(sec/60),s=String(sec%60).padStart(2,"0"),x=$("#countdown");if(x)x.textContent=`${m}:${s}`;if(sec<=0){clearInterval(APP.countdown);setToken("");APP.session=null;gate();toast(t("Tu acceso terminó.","Your access ended."))}};f();APP.countdown=setInterval(f,1000)}
async function route(x){if(x==="send")return send();if(x==="learn")return learn();if(x==="compare")return compare();if(x==="money")return moneyPage();if(x==="income")return incomePage();if(x==="expenses")return expensesPage();if(x==="savings")return savingsPage();if(x==="purchase")return purchasePage();if(x==="week")return weekPage();if(x==="family")return familyPage();if(x==="do")return doPage();if(x==="guide")return guide();if(x==="pdf")return moneyPDF();if(x==="learnpdf")return learningPDF();if(x==="assistant")return assistantPage();if(x==="help")return help();if(x==="privacy")return privacy()}
function back(title,content){shell(`<section class="section"><button class="btn secondary small" id="back">← ${t("Volver","Back")}</button><div class="section-title"><h1>${esc(title)}</h1></div>${content}</section>`);$("#back").onclick=home}
function send(){let s=APP.session||{};back(t("Preparar una remesa","Prepare a remittance"),`<div class="form-card"><p>${t("Dime lo necesario para saber qué debe pasar después. Los datos comerciales actuales se verifican antes de mostrarlos.","Tell me what is needed so the next step is clear. Current commercial data is verified before being shown.")}</p><div class="field"><label>${t("¿Cuánto quieres enviar?","How much do you want to send?")}</label><input id="amount" type="number" min=".01" max="1000000" step=".01" value="${esc(s.amount||"")}" placeholder="200"></div><div class="field"><label>${t("¿A qué país?","Which country?")}</label><select id="country">${countryOptions(s.destination_country||"")}</select></div><div class="field"><label>${t("¿Qué es más importante?","What matters most?")}</label><select id="priority"><option value="">${t("Todavía no lo sé","Not sure yet")}</option>${options(priorities,s.priority||"")}</select></div><div class="field"><label>${t("¿Es urgente?","Is it urgent?")}</label><select id="urgency"><option value="">${t("No indicado","Not specified")}</option><option value="yes"${s.urgency==="yes"?" selected":""}>${t("Sí","Yes")}</option><option value="no"${s.urgency==="no"?" selected":""}>${t("No","No")}</option></select></div><div class="field"><label>${t("¿Cómo quieres que reciba el dinero?","How should the recipient receive the money?")}</label><select id="delivery"><option value="">${t("Todavía no lo sé","Not sure yet")}</option>${options(delivery,s.delivery_method||"")}</select></div><div class="field"><label>${t("¿Cómo pagarías la remesa?","How would you pay for the remittance?")}</label><select id="payment"><option value="">${t("Todavía no lo sé","Not sure yet")}</option>${options(payment,s.payment_method||"")}</select></div><div class="field"><label>${t("¿Cuánto necesitas que reciba? (opcional)","How much must the recipient receive? (optional)")}</label><input id="target" type="number" min=".01" step=".01" value="${esc(s.recipient_amount_target||"")}"></div><div class="field"><label>${t("¿Con qué frecuencia?","How often?")}</label><select id="frequency"><option value="">${t("Una vez / no indicado","Once / not specified")}</option><option value="once">Una vez</option><option value="weekly">${t("Semanal","Weekly")}</option><option value="biweekly">${t("Cada dos semanas","Every two weeks")}</option><option value="monthly">${t("Mensual","Monthly")}</option><option value="other">${t("Otra","Other")}</option></select></div><div class="field"><label>${t("Necesidad especial (opcional)","Special need (optional)")}</label><input id="special" value="${esc(s.special_need||"")}"></div><div class="field"><label>${t("También puedes explicarlo con tus palabras","You can also explain it in your own words")}</label><textarea id="needText" rows="4" placeholder="${t("Ej. Necesito enviar $200 a México y quiero que llegue rápido.","Example: I need to send $200 to Mexico and want it delivered quickly.")}"></textarea></div><button class="btn" id="continueNeed">${t("Continuar","Continue")}</button></div>`);$("#continueNeed").onclick=submitNeed}
async function submitNeed(){let amount=Number($("#amount").value),country=$("#country").value,textv=$("#needText").value.trim();if(!amount||amount<.01||amount>1000000||!country)return toast(t("Completa un monto válido y un país.","Enter a valid amount and country."),"error");let p={language:APP.lang,amount,send_currency:"USD",destination_country:country,priority:$("#priority").value||null,urgency:$("#urgency").value||null,delivery_method:$("#delivery").value||null,payment_method:$("#payment").value||null,recipient_amount_target:Number($("#target").value)||null,frequency:$("#frequency").value||null,special_need:$("#special").value.trim()||null,free_text:textv||null,need_type:"remittance"};try{if(textv){let d=await api("/api/session/"+encodeURIComponent(APP.session.session_id)+"/need/parse",{method:"POST",body:JSON.stringify({language:APP.lang,text:textv,current_amount:amount,current_destination_country:country})});mergeSession(d)}let d=await api("/api/need",{method:"POST",body:JSON.stringify(p)});mergeSession(d);let q=await api("/api/session/"+encodeURIComponent(APP.session.session_id)+"/compare",{method:"POST",body:JSON.stringify(p)});mergeSession(q);showComparison(q)}catch(e){toast(e.message,"error")}}
function compare(){let s=APP.session||{};back(t("COMPARAR","COMPARE"),`<div class="form-card"><p>${t("Comparar significa mostrar diferencias verificables. No inventamos tarifa, tasa, tiempo ni disponibilidad.","Compare means showing verifiable differences. We do not invent fees, rates, delivery times or availability.")}</p><div class="field"><label>${t("Monto","Amount")}</label><input id="cmpAmount" type="number" min=".01" max="1000000" step=".01" value="${esc(s.amount||"")}"></div><div class="field"><label>${t("País","Country")}</label><select id="cmpCountry">${countryOptions(s.destination_country||"")}</select></div><div class="field"><label>${t("Prioridad","Priority")}</label><select id="cmpPriority"><option value="">${t("No indicada","Not specified")}</option>${options(priorities,s.priority||"")}</select></div><div class="field"><label>${t("Entrega","Delivery")}</label><select id="cmpDelivery"><option value="">${t("No indicada","Not specified")}</option>${options(delivery,s.delivery_method||"")}</select></div><div class="field"><label>${t("Pago","Payment")}</label><select id="cmpPayment"><option value="">${t("No indicado","Not specified")}</option>${options(payment,s.payment_method||"")}</select></div><div class="field"><label>${t("Urgencia","Urgency")}</label><select id="cmpUrgency"><option value="">${t("No indicada","Not specified")}</option><option value="yes"${s.urgency==="yes"?" selected":""}>${t("Sí","Yes")}</option><option value="no"${s.urgency==="no"?" selected":""}>${t("No","No")}</option></select></div><div class="field"><label>${t("Monto que debe recibir (opcional)","Recipient target (optional)")}</label><input id="cmpTarget" type="number" min=".01" step=".01" value="${esc(s.recipient_amount_target||"")}"></div><button class="btn" id="doCompare">${t("Comparar opciones","Compare options")}</button></div>`);$("#doCompare").onclick=async()=>{let amount=Number($("#cmpAmount").value),country=$("#cmpCountry").value;if(!amount||!country)return toast(t("Completa monto y país.","Complete amount and country."),"error");let p={language:APP.lang,amount,send_currency:"USD",destination_country:country,priority:$("#cmpPriority").value||null,urgency:$("#cmpUrgency").value||null,delivery_method:$("#cmpDelivery").value||null,payment_method:$("#cmpPayment").value||null,recipient_amount_target:Number($("#cmpTarget").value)||null,frequency:s.frequency||null,special_need:s.special_need||null};try{let d=await api("/api/session/"+APP.session.session_id+"/compare",{method:"POST",body:JSON.stringify(p)});mergeSession(d);showComparison(d)}catch(e){toast(e.message,"error")}}}
function providerMethods(p){let a=p?.delivery_methods||p?.methods||p?.declared_delivery_methods||[],b=p?.payment_methods||p?.declared_payment_methods||[];return`<p><strong>${t("Formas de entrega declaradas:","Declared delivery methods:")}</strong> ${esc(arr(a).map(text).join(", ")||t("No especificadas","Not specified"))}</p><p><strong>${t("Formas de pago declaradas:","Declared payment methods:")}</strong> ${esc(arr(b).map(text).join(", ")||t("No especificadas","Not specified"))}</p>`}
function providerData(p,status){if(status!=="verified")return`<div class="notice">${t("No hay datos comerciales actuales verificados para mostrar. Revisa el sitio oficial antes de tomar una decisión.","There are no verified current commercial data to show. Review the official site before making a decision.")}</div>`;let a=[];if(p.fee!=null)a.push(`<div class="metric"><small>${t("Tarifa","Fee")}</small><strong>${esc(text(p.fee))}</strong></div>`);if(p.exchange_rate!=null)a.push(`<div class="metric"><small>${t("Tasa","Rate")}</small><strong>${esc(text(p.exchange_rate))}</strong></div>`);if(p.recipient_amount!=null)a.push(`<div class="metric"><small>${t("Recibe","Recipient gets")}</small><strong>${esc(text(p.recipient_amount))}</strong></div>`);if(p.estimated_delivery!=null)a.push(`<div class="metric"><small>${t("Entrega estimada","Estimated delivery")}</small><strong>${esc(text(p.estimated_delivery))}</strong></div>`);if(p.availability!=null)a.push(`<div class="metric"><small>${t("Disponibilidad","Availability")}</small><strong>${esc(text(p.availability))}</strong></div>`);return`<div class="provider-data">${a.join("")||`<p>${t("No hay campos comerciales verificados para mostrar.","No verified commercial fields are available.")}</p>`}</div>`}
function showComparison(d){let r=arr(d.results),a=arr(d.available_providers),items=r.length?r:a;back(t("Opciones para revisar","Options to review"),`<div class="notice">${esc(d.explanation||t("Se muestran proveedores candidatos. La disponibilidad de un corredor no significa que una operación esté disponible en este momento.","Candidate providers are shown. A corridor catalog does not mean a transaction is currently available."))}</div>${d.differences?`<div class="card"><h3>${t("Qué cambia","What differs")}</h3><p>${esc(text(d.differences))}</p></div>`:""}<div class="result-list">${items.map(p=>{let id=p.provider_id||p.id,n=p.name||id,url=safeUrl(p.official_url||p.official_site),status=p.commercial_status||"unavailable";return`<div class="provider-card"><div class="provider-head"><div><h3>${esc(n)}</h3><span class="provider-status ${status==="verified"?"verified":""}">${status==="verified"?t("Datos verificados","Verified data"):t("Datos actuales no verificados","Current data not verified")}</span></div></div>${providerData(p,status)}${providerMethods(p)}${arr(p.requirements).length?`<p><strong>${t("Puede requerir:","May require:")}</strong> ${esc(arr(p.requirements).map(text).join(", "))}</p>`:""}<div class="hero-actions"><button class="btn small" data-provider="${esc(id)}">${t("Revisar esta opción","Review this option")}</button>${url?`<a class="btn secondary small" href="${esc(url)}" target="_blank" rel="noopener">${t("Sitio oficial","Official site")}</a>`:""}</div></div>`}).join("")||`<div class="empty">${t("No hay opciones para mostrar con los datos recibidos.","No options can be shown with the data received.")}</div>`}</div><div class="notice">${t("No se muestran rankings de mejor, más barato o más rápido cuando los datos actuales no están verificados.","No best, cheapest or fastest ranking is shown when current data is not verified.")}</div>`);document.querySelectorAll("[data-provider]").forEach(b=>b.onclick=()=>selectProvider(b.dataset.provider))}
async function selectProvider(id){try{let d=await api("/api/session/"+encodeURIComponent(APP.session.session_id)+"/select/"+encodeURIComponent(id),{method:"POST",body:"{}"});mergeSession(d);providerReview()}catch(e){toast(e.message,"error")}}
function providerReview(){let p=APP.session?.selected_option||{},name=p.name||p.provider_id||t("Proveedor seleccionado","Selected provider"),url=safeUrl(p.official_url||p.official_site);back(t("Revisar opción","Review option"),`<div class="card"><h2>${esc(name)}</h2>${providerData(p,p.commercial_status||"unavailable")}${providerMethods(p)}<div class="notice">${t("La app no crea la cuenta ni envía la transferencia. El siguiente paso es revisar la información en el sitio oficial.","The app does not create the account or send the transfer. The next step is to review the information on the official site.")}</div><div class="hero-actions"><button class="btn" id="reviewFinal">${t("Hacer revisión final","Run final review")}</button>${url?`<a class="btn secondary" href="${esc(url)}" target="_blank" rel="noopener">${t("Abrir sitio oficial","Open official site")}</a>`:""}</div></div>`);$("#reviewFinal").onclick=finalCheck}
async function finalCheck(){let s=APP.session||{},p=s.selected_option||{};if(!p.provider_id&&!p.id)return compare();let name=p.name||p.provider_id;back(t("REVISIÓN FINAL","FINAL REVIEW"),`<div class="form-card"><h2>${esc(name)}</h2><div class="field"><label>${t("¿Cómo recibirá el dinero?","How will the recipient receive the money?")}</label><select id="finalDelivery"><option value="">${t("Selecciona","Select")}</option>${options(delivery,s.delivery_method||"")}</select></div><div class="field"><label>${t("¿Cómo pagarás?","How will you pay?")}</label><select id="finalPayment"><option value="">${t("Selecciona","Select")}</option>${options(payment,s.payment_method||"")}</select></div><label class="check-row"><input id="recipientInfo" type="checkbox"${s.recipient_information_entered?" checked":""}> <span>${t("Ya tengo la información normal necesaria del destinatario y no estoy introduciendo contraseñas, CVV, OTP ni datos sensibles en REMESAS.","I have the normal recipient information needed and I am not entering passwords, CVV, OTP or sensitive data into REMESAS.")}</span></label><button class="btn" id="runFinal">${t("Revisar ahora","Review now")}</button></div><div id="finalResult"></div>`);$("#runFinal").onclick=async()=>{let delivery_method=$("#finalDelivery").value,payment_method=$("#finalPayment").value,recipient_information_entered=$("#recipientInfo").checked;if(!delivery_method||!recipient_information_entered){toast(t("Falta la forma de entrega o confirmar la información del destinatario.","Delivery method or recipient information confirmation is missing."),"error");return}try{let d=await api("/api/session/"+APP.session.session_id+"/final-check",{method:"POST",body:JSON.stringify({language:APP.lang,provider_id:p.provider_id||p.id,amount:Number(s.amount||0),send_currency:s.send_currency||"USD",destination_country:s.destination_country||"",delivery_method,payment_method,recipient_information_entered,checks:{}})});mergeSession(d);renderFinalResult(d)}catch(e){toast(e.message,"error")}}}
function renderFinalResult(d){let c=d.checks||{},ready=!!d.ready_to_continue,url=safeUrl(APP.session?.selected_option?.official_url);$("#finalResult").innerHTML=`<div class="card"><h2>${ready?t("Listo para pasar al proveedor","Ready to continue to provider"):t("Todavía falta algo","Something is still missing")}</h2><div class="list">${Object.keys(c).map(k=>`<div class="check-row"><span>${esc(k.replace(/_/g," "))}</span><strong>${c[k]===true?"✓":c[k]===false?"✕":esc(text(c[k]))}</strong></div>`).join("")}</div><div class="notice">${esc(d.important_note||t("Confirma todo nuevamente en el proveedor oficial.","Confirm everything again with the official provider."))}</div>${arr(d.precautions).length?`<div class="notice">${esc(arr(d.precautions).map(text).join(" · "))}</div>`:""}${ready?`<div class="hero-actions"><button class="btn" id="doAction">${t("HAGO · Ir al proveedor oficial","DO · Go to official provider")}</button><button class="btn secondary" id="quickAfter">${t("GUÍA RÁPIDA","QUICK GUIDE")}</button></div>`:""}<button class="btn secondary" id="needFinalHelp">${t("Necesito ayuda","I need help")}</button></div>`;$("#doAction")?.addEventListener("click",()=>doPage());$("#quickAfter")?.addEventListener("click",guide);$("#needFinalHelp").onclick=help}
function doPage(){let s=APP.session||{},p=s.selected_option||{},url=safeUrl(p.official_url||p.official_site),name=p.name||p.provider_id||t("Proveedor oficial","Official provider");back("HAGO · "+t("Siguiente acción","Next action"),`<div class="card"><h2>${esc(name)}</h2><p>${t("REMESAS ya organizó y revisó lo que puede revisar. Ahora tú decides si continúas en el sitio oficial.","REMESAS has organized and reviewed what it can review. Now you decide whether to continue on the official site.")}</p><div class="list"><div class="check-row"><span>${t("Monto","Amount")}</span><strong>${money(s.amount||0,s.send_currency||"USD")}</strong></div><div class="check-row"><span>${t("Destino","Destination")}</span><strong>${esc(s.destination_country||"")}</strong></div><div class="check-row"><span>${t("Entrega","Delivery")}</span><strong>${esc(s.delivery_method||t("No indicada","Not specified"))}</strong></div><div class="check-row"><span>${t("Pago","Payment")}</span><strong>${esc(s.payment_method||t("No indicado","Not specified"))}</strong></div></div><div class="notice">${t("REMESAS no inicia sesión, no introduce contraseñas, no confirma la operación y no recibe tu dinero.","REMESAS does not log in, enter passwords, confirm the transaction or receive your money.")}</div>${url?`<button class="btn" id="officialGo">${t("ABRIR SITIO OFICIAL","OPEN OFFICIAL SITE")}</button>`:`<div class="notice">${t("No hay una URL oficial disponible en los datos recibidos.","No official URL is available in the received data.")}</div>`}</div>`);if(url)$("#officialGo").onclick=()=>window.open(url,"_blank","noopener")}
async function learn(){try{let d=await api("/api/learn"),lessons=arr(d.lessons);back(t("APRENDER","LEARN"),`<div class="notice">${esc(d.notice||t("Contenido educativo original. No es entrenamiento oficial de proveedores.","Original educational content. It is not official provider training."))}</div><div class="grid two">${lessons.map((l,i)=>`<button class="action-card" data-lesson="${i}"><span class="action-icon">📘</span><strong>${esc(text(l.title||l.name||`Lección ${i+1}`))}</strong><small>${esc(text(l.purpose||""))}</small></button>`).join("")}</div><section class="section"><h2>${t("Aprender sobre proveedores","Learn about providers")}</h2><div class="grid two">${providers().map(p=>`<button class="action-card" data-learnprovider="${esc(p.id||"")}"><strong>${esc(p.name||p.id)}</strong><small>${t("Proceso general + sitio oficial","General process + official site")}</small></button>`).join("")}</div></section>`);document.querySelectorAll("[data-lesson]").forEach(b=>b.onclick=()=>lesson(lessons[Number(b.dataset.lesson)]));document.querySelectorAll("[data-learnprovider]").forEach(b=>b.onclick=()=>providerLearn(b.dataset.learnprovider))}catch(e){toast(e.message,"error")}}
function lesson(l){if(!l)return;let teach=l.teaches||l.checklist||l.steps||[],warn=l.warnings||l.warning||[];back(text(l.title||t("Lección","Lesson")),`<div class="card"><h2>${esc(text(l.purpose||""))}</h2><div class="list">${arr(teach).map((x,i)=>`<div class="check-row"><strong>${i+1}.</strong><span>${esc(text(x))}</span></div>`).join("")}</div>${arr(warn).length?`<div class="notice">${esc(arr(warn).map(text).join(" · "))}</div>`:""}</div>`)}
async function providerLearn(id){try{let d=await api("/api/learn/"+encodeURIComponent(id)),steps=arr(d.steps),url=safeUrl(d.official_url||d.official_site);back(text(d.title||id),`<div class="notice">${esc(d.disclaimer||t("Información educativa original. Confirma la información actual con el proveedor.","Original educational information. Confirm current information with the provider."))}</div><div class="card"><div class="list">${steps.map((x,i)=>`<div class="check-row"><strong>${i+1}.</strong><span>${esc(text(x))}</span></div>`).join("")}</div>${d.current_info_notice?`<div class="notice">${esc(text(d.current_info_notice))}</div>`:""}${providerMethods(d)}</div>${url?`<a class="btn" href="${esc(url)}" target="_blank" rel="noopener">${t("Confirmar en sitio oficial","Confirm on official site")}</a>`:""}`)}catch(e){toast(e.message,"error")}}
async function guide(){try{let d=await api("/api/quick-guide"),steps=arr(d.steps),url=safeUrl(d.official_url||d.official_site);back(t("GUÍA RÁPIDA","QUICK GUIDE"),`<div class="card">${d.provider?`<h2>${esc(text(d.provider.name||d.provider))}</h2>`:""}<div class="list">${steps.map((x,i)=>`<div class="check-row"><strong>${i+1}.</strong><span>${esc(text(x))}</span></div>`).join("")}</div></div><div class="notice">${esc(text(d.final_action||t("Revisa siempre el proveedor oficial antes de enviar.","Always review the official provider before sending.")))}</div>${d.limits?`<div class="notice">${esc(text(d.limits))}</div>`:""}${url?`<a class="btn" href="${esc(url)}" target="_blank" rel="noopener">${t("Sitio oficial","Official site")}</a>`:""}`)}catch(e){toast(e.message,"error")}}
async function help(){try{let d=await api("/api/help"),topics=Array.isArray(d)?d:arr(d.topics||Object.values(d));back(t("AYUDA","HELP"),`<div class="grid two">${topics.map(x=>`<button class="action-card" data-help="${esc(x.id||"")}"><strong>${esc(text(x.label||x.title||x.id))}</strong><small>${esc(text(x.answer||x.description||""))}</small></button>`).join("")}</div>`);document.querySelectorAll("[data-help]").forEach(b=>b.onclick=()=>{let x=topics.find(z=>(z.id||"")===b.dataset.help);modal(text(x?.label||t("Ayuda","Help")),`<p>${esc(text(x?.answer||x?.description||""))}</p>`)})}catch(e){toast(e.message,"error")}}
function assistantPage(){back(t("ASISTENTE","ASSISTANT"),`<div class="assistant"><div class="assistant-box">${t("Escribe lo que necesitas. La app intentará aclarar la siguiente acción.","Write what you need. The app will try to clarify the next action.")}</div><form id="assistantForm" class="form-card"><div class="field"><label>${t("¿Qué necesitas?","What do you need?")}</label><textarea id="assistantText" rows="5" required placeholder="${t("Ej. ¿Qué necesito para enviar dinero a mi familia?","Example: What do I need to send money to my family?")}"></textarea></div><button class="btn">${t("Preguntar","Ask")}</button></form><div id="assistantResult"></div></div>`);$("#assistantForm").onsubmit=async e=>{e.preventDefault();let tx=$("#assistantText").value.trim();if(!tx)return;try{let d=await api("/api/assistant",{method:"POST",body:JSON.stringify({language:APP.lang,text:tx})}),r=d.reply||d.answer||d.message||d;$("#assistantResult").innerHTML=`<div class="card"><p>${esc(text(r))}</p>${d.official_url&&safeUrl(d.official_url)?`<a class="btn secondary" href="${esc(safeUrl(d.official_url))}" target="_blank" rel="noopener">${t("Fuente oficial","Official source")}</a>`:""}</div>`}catch(e){toast(e.message,"error")}}}
function privacy(){back(t("Privacidad y seguridad","Privacy and security"),`<div class="privacy"><h2>${t("Tus datos de dinero","Your money data")}</h2><p>${t("Los registros de dinero, ingresos, gastos, familia, ahorros y compras se guardan localmente en este navegador.","Money, income, expense, family, savings and purchase records are stored locally in this browser.")}</p><p>${t("REMESAS no pide contraseñas bancarias, contraseñas de proveedores, CVV, OTP ni números completos de tarjeta.","REMESAS does not ask for bank passwords, provider passwords, CVV, OTP or full card numbers.")}</p><p>${t("No hacemos transferencias ni enviamos formularios por ti.","We do not execute transfers or submit forms for you.")}</p><button class="btn danger" id="deleteLocal">${t("Borrar mis datos locales","Delete my local data")}</button><button class="btn secondary" id="importBtn">${t("Restaurar PDF REMESAS","Restore REMESAS PDF")}</button><input id="pdfFile" type="file" accept=".pdf" class="hidden"></div>`);$("#deleteLocal").onclick=()=>{[APP.moneyKey,APP.incomeKey,APP.expensesKey,APP.familyKey,APP.savingsKey,APP.purchasesKey,APP.prefsKey].forEach(k=>localStorage.removeItem(k));toast(t("Datos locales borrados.","Local data deleted."));home()};$("#importBtn").onclick=()=>$("#pdfFile").click();$("#pdfFile").onchange=e=>importPDF(e.target.files[0])}
function moneyPage(){let m=load(APP.moneyKey,{income:0,balance:0});back(t("TENGO · Mi dinero","HAVE · My money"),`<form id="moneyForm" class="form-card"><p>${t("Aquí dices cuánto tienes disponible ahora. Esto no es una cuenta bancaria.","Here you record what is available now. This is not a bank account.")}</p><div class="field"><label>${t("Dinero disponible ahora","Money available now")}</label><input id="balance" type="number" min="0" step=".01" value="${Number(m.balance||0)}"></div><div class="field"><label>${t("Ingreso acumulado","Total income")}</label><input id="income" type="number" min="0" step=".01" value="${Number(m.income||0)}"></div><button class="btn">${t("Guardar","Save")}</button></form>`);$("#moneyForm").onsubmit=e=>{e.preventDefault();save(APP.moneyKey,{balance:Number($("#balance").value||0),income:Number($("#income").value||0),updated_at:dateTime()});toast(t("Guardado en este dispositivo.","Saved on this device."));home()}}
function incomePage(){let a=load(APP.incomeKey,[]);back(t("GANO · Lo que entra","EARN · What comes in"),`<form id="incForm" class="form-card"><div class="field"><label>${t("¿De dónde viene?","Where is it from?")}</label><input id="incDesc" required></div><div class="field"><label>${t("Cantidad","Amount")}</label><input id="incVal" type="number" min=".01" step=".01" required></div><button class="btn">${t("Registrar ingreso","Record income")}</button></form><div class="list">${a.map((x,i)=>`<div class="check-row"><span>${esc(x.desc)}<small>${esc(x.date||"")}</small></span><strong>${money(x.amount)}</strong><button class="btn danger small" data-incdel="${i}">×</button></div>`).join("")||`<div class="empty">${t("Todavía no hay ingresos registrados.","No income recorded yet.")}</div>`}</div>`);$("#incForm").onsubmit=e=>{e.preventDefault();let v=Number($("#incVal").value||0);if(v<=0)return;let m=load(APP.moneyKey,{income:0,balance:0});a.push({desc:$("#incDesc").value.trim(),amount:v,date:dateTime()});m.income=Number(m.income||0)+v;m.balance=Number(m.balance||0)+v;save(APP.incomeKey,a);save(APP.moneyKey,m);incomePage()};document.querySelectorAll("[data-incdel]").forEach(b=>b.onclick=()=>{let i=Number(b.dataset.incdel),x=a[i],m=load(APP.moneyKey,{income:0,balance:0});a.splice(i,1);m.income=Math.max(0,Number(m.income||0)-Number(x.amount||0));m.balance=Number(m.balance||0)-Number(x.amount||0);save(APP.incomeKey,a);save(APP.moneyKey,m);incomePage()})}
function expensesPage(){let a=load(APP.expensesKey,[]);back(t("GASTO · Lo que sale","SPEND · What goes out"),`<form id="expForm" class="form-card"><div class="field"><label>${t("Descripción","Description")}</label><input id="desc" required></div><div class="field"><label>${t("Cantidad","Amount")}</label><input id="val" type="number" min=".01" step=".01" required></div><button class="btn">${t("Registrar gasto","Record expense")}</button></form><div class="list">${a.map((x,i)=>`<div class="check-row"><span>${esc(x.desc)}<small>${esc(x.date||"")}</small></span><strong>${money(x.amount)}</strong><button class="btn danger small" data-del="${i}">×</button></div>`).join("")||`<div class="empty">${t("Todavía no hay gastos.","No expenses yet.")}</div>`}</div>`);$("#expForm").onsubmit=e=>{e.preventDefault();let v=Number($("#val").value||0);if(v<=0)return;let m=load(APP.moneyKey,{income:0,balance:0});a.push({desc:$("#desc").value.trim(),amount:v,date:dateTime()});m.balance=Number(m.balance||0)-v;save(APP.expensesKey,a);save(APP.moneyKey,m);expensesPage()};document.querySelectorAll("[data-del]").forEach(b=>b.onclick=()=>{let i=Number(b.dataset.del),x=a[i],m=load(APP.moneyKey,{income:0,balance:0});a.splice(i,1);m.balance=Number(m.balance||0)+Number(x.amount||0);save(APP.expensesKey,a);save(APP.moneyKey,m);expensesPage()})}
function savingsPage(){let a=load(APP.savingsKey,[]);back(t("AHORRO · Lo que separas","SAVE · What you set aside"),`<form id="savForm" class="form-card"><div class="field"><label>${t("¿Para qué ahorras?","What are you saving for?")}</label><input id="goal" required></div><div class="field"><label>${t("Cantidad que quieres separar","Amount you want to set aside")}</label><input id="savVal" type="number" min=".01" step=".01" required></div><button class="btn">${t("Guardar ahorro","Save savings")}</button></form><div class="list">${a.map((x,i)=>`<div class="check-row"><span>${esc(x.goal)}<small>${esc(x.date||"")}</small></span><strong>${money(x.amount)}</strong><button class="btn danger small" data-savdel="${i}">×</button></div>`).join("")||`<div class="empty">${t("Todavía no hay ahorros registrados.","No savings recorded yet.")}</div>`}</div>`);$("#savForm").onsubmit=e=>{e.preventDefault();let v=Number($("#savVal").value||0);if(v<=0)return;a.push({goal:$("#goal").value.trim(),amount:v,date:dateTime()});save(APP.savingsKey,a);savingsPage()};document.querySelectorAll("[data-savdel]").forEach(b=>b.onclick=()=>{a.splice(Number(b.dataset.savdel),1);save(APP.savingsKey,a);savingsPage()})}
function purchasePage(){let a=load(APP.purchasesKey,[]);back(t("QUIERO · Compras","WANT · Purchases"),`<form id="purForm" class="form-card"><div class="field"><label>${t("¿Qué quieres comprar?","What do you want to buy?")}</label><input id="item" required></div><div class="field"><label>${t("Costo estimado","Estimated cost")}</label><input id="cost" type="number" min=".01" step=".01" required></div><button class="btn">${t("Guardar plan","Save plan")}</button></form><div class="list">${a.map((x,i)=>`<div class="check-row"><span>${esc(x.item)}<small>${esc(x.date||"")}</small></span><strong>${money(x.cost)}</strong><button class="btn danger small" data-purdel="${i}">×</button></div>`).join("")||`<div class="empty">${t("No hay compras planeadas.","No planned purchases.")}</div>`}</div>`);$("#purForm").onsubmit=e=>{e.preventDefault();a.push({item:$("#item").value.trim(),cost:Number($("#cost").value||0),date:dateTime()});save(APP.purchasesKey,a);purchasePage()};document.querySelectorAll("[data-purdel]").forEach(b=>b.onclick=()=>{a.splice(Number(b.dataset.purdel),1);save(APP.purchasesKey,a);purchasePage()})}
function familyPage(){let a=load(APP.familyKey,[]);back(t("FAMILIA · Personas y necesidades","FAMILY · People and needs"),`<form id="famForm" class="form-card"><div class="field"><label>${t("Nombre o apodo","Name or nickname")}</label><input id="famName" required></div><div class="field"><label>${t("¿Qué necesita?","What is needed?")}</label><input id="famNeed" required></div><div class="field"><label>${t("Cantidad aproximada (opcional)","Approximate amount (optional)")}</label><input id="famAmount" type="number" min=".01" step=".01"></div><button class="btn">${t("Guardar","Save")}</button></form><div class="list">${a.map((x,i)=>`<div class="check-row"><span><strong>${esc(x.name)}</strong><small>${esc(x.need)} · ${esc(x.date||"")}</small></span><strong>${x.amount?money(x.amount):""}</strong><button class="btn danger small" data-famdel="${i}">×</button></div>`).join("")||`<div class="empty">${t("Todavía no hay personas registradas.","No people recorded yet.")}</div>`}</div>`);$("#famForm").onsubmit=e=>{e.preventDefault();a.push({name:$("#famName").value.trim(),need:$("#famNeed").value.trim(),amount:Number($("#famAmount").value||0),date:dateTime()});save(APP.familyKey,a);familyPage()};document.querySelectorAll("[data-famdel]").forEach(b=>b.onclick=()=>{a.splice(Number(b.dataset.famdel),1);save(APP.familyKey,a);familyPage()})}
function weekPage(){let m=load(APP.moneyKey,{income:0,balance:0}),e=load(APP.expensesKey,[]),s=load(APP.savingsKey,[]),p=load(APP.purchasesKey,[]),spent=e.reduce((a,x)=>a+Number(x.amount||0),0),saved=s.reduce((a,x)=>a+Number(x.amount||0),0),planned=p.reduce((a,x)=>a+Number(x.cost||0),0),available=Number(m.balance||0)-saved;back(t("PUEDO · Mi semana","CAN · My week"),`<div class="balance-grid"><div class="balance"><small>${t("Disponible actual","Current available")}</small><strong>${money(m.balance)}</strong></div><div class="balance"><small>${t("Gastos registrados","Recorded expenses")}</small><strong>${money(spent)}</strong></div><div class="balance"><small>${t("Ahorro separado","Set aside")}</small><strong>${money(saved)}</strong></div><div class="balance"><small>${t("Disponible después de ahorro","Available after savings")}</small><strong>${money(available)}</strong></div></div><div class="card"><h2>${t("Lo que planeas","What you plan")}</h2><div class="check-row"><span>${t("Compras planeadas","Planned purchases")}</span><strong>${money(planned)}</strong></div><div class="check-row"><span>${t("Cantidad de planes","Number of plans")}</span><strong>${p.length}</strong></div></div><div class="notice">${t("El cálculo usa únicamente los datos que registraste en este dispositivo. No es asesoría financiera.","The calculation uses only the data you recorded on this device. It is not financial advice.")}</div>`)}
function pdfBase(title,body){let w=window.open("","_blank");if(!w)return toast(t("El navegador bloqueó la ventana.","The browser blocked the window."),"error");let html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;margin:40px;color:#172033}h1{margin-bottom:4px}.box{border:1px solid #ddd;border-radius:10px;padding:15px;margin:15px 0}.row{display:flex;justify-content:space-between;gap:20px;padding:7px 0;border-bottom:1px solid #eee}.notice{margin-top:25px;padding:12px;background:#f4f7fb}.footer{margin-top:35px;font-size:12px;color:#667085}small{color:#667085}</style></head><body><h1>${esc(title)}</h1><small>${esc(day())} · ${esc(dateTime())}</small>${body}<div class="notice">${t("PDF generado por REMESAS para organizar y revisar tus propios registros. No es software de impuestos ni sustituye al contador.","PDF generated by REMESAS to organize and review your own records. It is not tax software and does not replace a tax preparer.")}</div><div class="footer">May Roga LLC · REMESAS ${APP.version}</div><script>setTimeout(()=>window.print(),300)<\/script></body></html>`;w.document.write(html);w.document.close()}
function moneyPDF(){let m=load(APP.moneyKey,{income:0,balance:0}),inc=load(APP.incomeKey,[]),e=load(APP.expensesKey,[]),s=load(APP.savingsKey,[]),p=load(APP.purchasesKey,[]),f=load(APP.familyKey,[]),spent=e.reduce((a,x)=>a+Number(x.amount||0),0),saved=s.reduce((a,x)=>a+Number(x.amount||0),0),body=`<div class="box"><h2>${t("Resumen","Summary")}</h2><div class="row"><span>${t("Disponible","Available")}</span><b>${money(m.balance)}</b></div><div class="row"><span>${t("Ingresos acumulados","Total income")}</span><b>${money(m.income)}</b></div><div class="row"><span>${t("Gastos registrados","Recorded expenses")}</span><b>${money(spent)}</b></div><div class="row"><span>${t("Ahorros registrados","Recorded savings")}</span><b>${money(saved)}</b></div></div><div class="box"><h2>${t("Ingresos","Income")}</h2>${inc.map(x=>`<div class="row"><span>${esc(x.desc)}<small>${esc(x.date||"")}</small></span><b>${money(x.amount)}</b></div>`).join("")||`<p>${t("Sin registros.","No records.")}</p>`}</div><div class="box"><h2>${t("Gastos","Expenses")}</h2>${e.map(x=>`<div class="row"><span>${esc(x.desc)}<small>${esc(x.date||"")}</small></span><b>${money(x.amount)}</b></div>`).join("")||`<p>${t("Sin registros.","No records.")}</p>`}</div><div class="box"><h2>${t("Ahorros","Savings")}</h2>${s.map(x=>`<div class="row"><span>${esc(x.goal)}<small>${esc(x.date||"")}</small></span><b>${money(x.amount)}</b></div>`).join("")||`<p>${t("Sin registros.","No records.")}</p>`}</div><div class="box"><h2>${t("Compras planeadas","Planned purchases")}</h2>${p.map(x=>`<div class="row"><span>${esc(x.item)}<small>${esc(x.date||"")}</small></span><b>${money(x.cost)}</b></div>`).join("")||`<p>${t("Sin registros.","No records.")}</p>`}</div><div class="box"><h2>${t("Familia","Family")}</h2>${f.map(x=>`<div class="row"><span>${esc(x.name)} — ${esc(x.need)}</span><b>${x.amount?money(x.amount):""}</b></div>`).join("")||`<p>${t("Sin registros.","No records.")}</p>`}</div>`;pdfBase(t("REMESAS · Mis datos","REMESAS · My data"),body)}
async function learningPDF(){try{let d=await api("/api/learning-pdf"),steps=arr(d.steps||d.lessons||d.content),urls=arr(d.official_urls);let body=`<div class="box"><h2>${esc(text(d.title||t("Guía APRENDER","LEARN Guide")))}</h2>${steps.map((x,i)=>`<div class="row"><span>${i+1}. ${esc(text(x))}</span></div>`).join("")}</div><div class="box"><h2>${t("Fuentes oficiales","Official sources")}</h2>${urls.map(u=>`<div class="row"><span>${esc(text(u))}</span></div>`).join("")}</div>`;pdfBase(text(d.title||t("Guía APRENDER","LEARN Guide")),body)}catch(e){toast(e.message,"error")}}
async function importPDF(file){if(!file)return;toast(t("El navegador no puede convertir de forma segura un PDF externo en registros. El PDF generado sirve como documento de respaldo; para restaurar automáticamente se necesita una lectura de PDF compatible en el servidor.","The browser cannot safely convert an external PDF into records. The generated PDF serves as a backup document; automatic restoration requires compatible PDF reading on the server."),"error")}
async function loadConfig(){try{let r=await fetch("/api/config?language="+encodeURIComponent(APP.lang)),d=await r.json();if(!r.ok)throw Error(d.detail||"Config error");APP.config=d}catch(e){APP.config={countries:countryList(),providers:providers()}}}
(async()=>{await boot()})();
